'use strict';
const R=Ritm,KEY='ritm-v1',$=s=>document.querySelector(s),names=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],periods={morning:'Утро',day:'День',evening:'Вечер'};
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateText=d=>R.parse(d).toLocaleDateString('ru',{day:'numeric',month:'long'});
let state={version:2,habits:[],logs:{}},selected=R.today(),view='today',month=selected.slice(0,7),editing=null,archiveView=false,filter='all',statsHabit='',timer,undoAction,blocked=false,importData=null,editSnapshot='',lastDay=R.today();
const templates=[{name:'Читать книгу',icon:'📖',type:'count',target:20,unit:'стр.',step:5,period:'evening'},{name:'Пить воду',icon:'💧',type:'count',target:8,unit:'стак.',step:1,period:'day'},{name:'Утренняя зарядка',icon:'☀',type:'minutes',target:10,unit:'мин.',step:5,period:'morning'},{name:'Учить английский',icon:'✦',type:'minutes',target:15,unit:'мин.',step:5,period:'day'}];
function notify(message,undo){clearTimeout(timer);undoAction=undo;$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?'<button id="undo">Отменить</button>':''}`;$('#toast').classList.add('visible');timer=setTimeout(()=>{$('#toast').classList.remove('visible');undoAction=null},undo?9000:5000)}
function load(){try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);state=R.migrate(parsed);if(!parsed.version&&!localStorage.getItem('ritm-before-v2'))localStorage.setItem('ritm-before-v2',raw)}}catch{blocked=true}}
async function transact(action){
  if(window.RitmWriting){notify('Дождитесь сохранения предыдущего действия.');return false}
  if(blocked){notify(RitmCloud.launched?'Сначала загрузите прогресс из Telegram.':'Сначала восстановите данные из копии.');return false}
  window.RitmWriting=true;
  try{const raw=RitmCloud.launched?null:localStorage.getItem(KEY),next=raw?R.migrate(JSON.parse(raw)):structuredClone(state);action(next);if(!R.validate(next))throw Error('Некорректные данные');
    if(RitmCloud.launched)state=await RitmCloud.save(next);else{localStorage.setItem(KEY,JSON.stringify(next));state=next}render();return true;
  }catch(e){notify(RitmCloud.launched?e.message:e.message.startsWith('Привычка')?e.message:'Не удалось сохранить. Проверьте хранилище браузера и сделайте экспорт.');const draftButton=$('#cloud-draft');if(draftButton)draftButton.hidden=!RitmCloud.draft;return false}
  finally{window.RitmWriting=false}
}
async function progress(id,amount,date=selected){if(!Number.isInteger(amount)||amount<0||amount>100000||date>R.today())return false;let previous=0;const ok=await transact(s=>{const h=s.habits.find(h=>h.id===id);if(!h||!R.scheduled(s,h,date))throw Error('Привычка недоступна на этот день.');previous=R.value(s,h,date);s.logs[date]??={};s.logs[date][id]=amount});if(ok)notify(amount?'Прогресс сохранён':'Отметка снята',()=>transact(s=>{if(s.logs[date]?.[id]!==amount)throw Error('Привычка уже изменена в другой вкладке.');s.logs[date][id]=previous}));return ok}
function row(h,management=false){const c=R.configAt(h,selected),v=R.value(state,h,selected),done=R.done(state,h,selected),w=R.weekly(state,h,selected),s=R.streak(state,h);const schedule=h.schedule==='weekly'?`${h.frequency} раза в неделю`:h.days.length===7?'Каждый день':h.days.map(d=>names[d]).join(', '),upcoming=h.revisions.find(r=>r.from>R.today());return `<article class="habit ${done?'done':''}" data-habit="${h.id}"><div class="habit-icon">${esc(h.icon)}</div><div class="habit-info"><strong>${esc(h.name)}</strong><small>${management?esc(schedule):c.type==='check'?(done?'Выполнено':'Один шаг к вашей цели'):`${v} из ${c.target} ${esc(c.unit)}`}${!management&&c.schedule==='weekly'?` · ${w.complete}/${w.target} за неделю`:''}${s.current?` <span class="streak">${s.current} ${s.unit} подряд</span>`:''}</small>${upcoming?`<small class="upcoming">Новая цель с ${dateText(upcoming.from)}</small>`:''}${!management&&c.type!=='check'?`<div class="track"><span style="width:${Math.min(v/c.target*100,100)}%"></span></div>`:''}</div><div class="habit-actions">${management?`<button class="text-button" data-archive="${h.id}">${h.archivedAt?'Вернуть':'В архив'}</button>`:c.type!=='check'?`<div class="quantity"><button data-minus="${h.id}" aria-label="Уменьшить: ${esc(h.name)}" ${v===0?'disabled':''}>−</button><button class="value-button" data-value="${h.id}" aria-label="Ввести прогресс: ${esc(h.name)}">${v}</button><button data-plus="${h.id}" aria-label="Добавить: ${esc(h.name)}">+</button></div>`:''}${management?'':`<button class="complete" data-check="${h.id}" aria-pressed="${done}" aria-label="${done?'Отменить':'Выполнить'}: ${esc(h.name)}">✓</button>`}<button class="edit" data-edit="${h.id}" aria-label="Редактировать: ${esc(h.name)}">⋯</button></div></article>`}
function weekStrip(){const start=R.monday(selected);return `<div class="week-toolbar"><button class="icon-button" data-week="-7" aria-label="Предыдущая неделя">‹</button><span>${dateText(start)} — ${dateText(R.shift(start,6))}</span><button class="text-button" data-today ${selected===R.today()?'disabled':''}>Сегодня</button><button class="icon-button" data-week="7" aria-label="Следующая неделя" ${R.shift(start,7)>R.today()?'disabled':''}>›</button></div><div class="week">${Array.from({length:7},(_,i)=>{const d=R.shift(start,i),t=R.dayStats(state,d);return `<button class="day ${d===selected?'selected':''} ${d===R.today()?'is-today':''}" data-date="${d}" aria-label="${dateText(d)}: ${t.complete} из ${t.total}" aria-pressed="${d===selected}" ${d>R.today()?'disabled':''}><span>${names[i]}</span><b>${R.parse(d).getDate()}</b><i class="${t.complete?'marked':''}"></i></button>`}).join('')}</div>`}
function sidebar(){const w=R.weekStats(state,selected),start=R.monday(selected),victories=Object.entries(state.logs).reduce((n,[d,logs])=>n+state.habits.filter(h=>(logs[h.id]||0)>=R.configAt(h,d).target).length,0);return `<div class="right-column"><section class="card week-card"><div class="card-label">НЕДЕЛЬНЫЙ ОБЗОР</div><div class="big-number">${w.percent}<span>%</span></div><p class="muted">${w.complete} из ${w.target} целей выполнено</p><div class="bars" aria-label="Выполнение ежедневных привычек по дням">${Array.from({length:7},(_,i)=>{const d=R.shift(start,i),t=R.dayStats(state,d),p=t.total?t.complete/t.total*100:0;return `<div class="bar-column"><div class="bar-space"><div class="bar ${d===selected?'today':''}" style="height:${Math.max(p,4)}%" title="${dateText(d)}: ${t.complete} из ${t.total}"></div></div><span>${names[i]}</span></div>`}).join('')}</div><p class="muted footnote">Дневные цели — до сегодня.<br>Недельные — на всю неделю.</p></section><section class="card"><h2>Ваши маленькие победы</h2><div class="stat-line"><span>Выполнено всего</span><b>${victories}</b></div><div class="stat-line"><span>Активных привычек</span><b>${state.habits.filter(h=>!h.archivedAt).length}</b></div></section><section class="card tip"><div class="tip-icon">✧</div><strong>Возвращаться — тоже привычка</strong><p>Один пропуск не отменяет прогресс. Продолжайте с того места, где вы сейчас.</p></section></div>`}
function starter(){return `<section class="starter"><div class="starter-top"><span class="starter-symbol">✦</span><h2>Одна привычка — хорошее начало</h2><p>Выберите пример и настройте его под себя.</p></div><div class="template-grid">${templates.map((t,i)=>`<button class="template" data-template="${i}"><span>${t.icon}</span><strong>${t.name}</strong><small>${t.target} ${t.unit} в день</small><b>+</b></button>`).join('')}</div><button class="text-button" data-create>Создать свою привычку</button></section>`}
function todayPage(){const t=R.dayStats(state,selected),daily=R.daily(state,selected),weekly=state.habits.filter(h=>R.scheduled(state,h,selected)&&R.configAt(h,selected).schedule==='weekly'),show=h=>filter==='all'||(filter==='todo'?!R.done(state,h,selected):R.done(state,h,selected));return `<div class="dashboard"><div class="main-column"><section class="summary ${t.total&&t.complete===t.total?'is-complete':''}"><div><div class="eyebrow">${selected===R.today()?'ПРОТОКОЛ НА СЕГОДНЯ':dateText(selected).toUpperCase()}</div><h2>${t.total?`${t.complete} из ${t.total} выполнено`:weekly.length?'На этой неделе':state.habits.length?'День без обязательств':'Начнём с одного шага'}</h2><p>${t.total?(t.complete===t.total?'План на день выполнен. Отличная работа.':`Осталось ${t.total-t.complete}. Продолжайте в своём темпе.`):(weekly.length?'Выберите удобный день для недельной цели.':state.habits.length?'Сегодня можно отдохнуть или заняться недельными целями.':'Выберите готовый пример ниже или создайте свою привычку.')}</p></div><div class="ring" style="--progress:${t.total?t.complete/t.total*100:0}%" aria-label="${t.complete} из ${t.total} ежедневных привычек"><div><b>${t.total?Math.round(t.complete/t.total*100):0}%</b><small>за день</small></div></div></section>${weekStrip()}${!state.habits.length?starter():`<div class="section-title"><h2>План на день</h2><div class="segmented" aria-label="Фильтр привычек">${[['all','Все'],['todo','Осталось'],['done','Готово']].map(([id,label])=>`<button data-filter="${id}" class="${filter===id?'active':''}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div></div>${Object.entries(periods).map(([p,label])=>{const list=daily.filter(h=>h.period===p&&show(h));return list.length?`<div class="period-title"><span>${label}</span><span>${list.length}</span></div>${list.map(h=>row(h)).join('')}`:''}).join('')}${!daily.filter(show).length?`<div class="empty compact ${filter==='todo'&&daily.length?'empty-success':''}">${filter==='done'?'Пока нет выполненных привычек.':filter==='todo'&&daily.length?'На сегодня всё готово. Можно выдохнуть.':'На этот день нет ежедневных привычек.'}</div>`:''}${weekly.length?`<div class="section-title weekly-heading"><h2>В течение недели</h2><small>Вы выбираете день</small></div><p class="section-note">Эти цели не влияют на процент выполнения дня.</p>${weekly.filter(show).map(h=>row(h)).join('') || '<div class="empty compact">Нет привычек с этим статусом.</div>'}`:''}`}</div>${sidebar()}</div>`}
function statsPage(){const first=month+'-01',count=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate(),habits=statsHabit?state.habits.filter(h=>h.id===statsHabit):state.habits;let completions=0,activeDays=0;const cells=Array.from({length:count},(_,i)=>{const d=R.shift(first,i),eligible=habits.filter(h=>R.scheduled(state,h,d)),finished=eligible.filter(h=>R.done(state,h,d)).length;completions+=finished;if(finished)activeDays++;return `<button data-date="${d}" class="${finished?(finished===eligible.length?'full':'has'):''} ${d===R.today()?'calendar-today':''}" ${d>R.today()?'disabled':''} aria-label="${dateText(d)}: ${finished} выполнено"><b>${i+1}</b><small>${finished||'·'}</small></button>`}).join('');return `<div class="stats-toolbar"><label>Привычка<select id="stats-habit"><option value="">Все привычки</option>${state.habits.map(h=>`<option value="${h.id}" ${statsHabit===h.id?'selected':''}>${esc(h.name)}${h.archivedAt?' · архив':''}</option>`).join('')}</select></label><div class="mini-stat"><strong>${completions}</strong><span>выполнений за месяц</span></div><div class="mini-stat"><strong>${activeDays}</strong><span>дней с прогрессом</span></div></div>${analyticsPanel()}<div class="stats-grid"><section class="card calendar-card"><div class="month-nav"><button class="icon-button" data-month="-1" aria-label="Предыдущий месяц">‹</button><h2>${R.parse(first).toLocaleDateString('ru',{month:'long',year:'numeric'})}</h2><button class="icon-button" data-month="1" aria-label="Следующий месяц" ${month>=R.today().slice(0,7)?'disabled':''}>›</button></div><div class="calendar">${names.map(n=>`<span>${n}</span>`).join('')}${'<span></span>'.repeat(R.weekday(first))}${cells}</div><div class="legend"><span><i></i> Нет отметок</span><span><i class="some"></i> Есть прогресс</span><span><i class="all"></i> Всё выполнено</span></div><p class="muted">Нажмите на день, чтобы открыть его привычки и исправить отметки.</p></section><section class="card"><h2>Регулярность</h2><p class="muted">Серии учитывают ваше расписание. Выходные и дни в архиве не обрывают серию.</p>${habits.map(h=>{const s=R.streak(state,h);return `<div class="streak-row"><div class="habit-icon">${esc(h.icon)}</div><div><strong>${esc(h.name)}</strong><small>Лучшая серия: ${s.best} ${s.unit}</small></div><b>${s.current}<small>${s.unit}</small></b></div>`}).join('')||'<div class="empty compact">Первые отметки начнут вашу историю.</div>'}</section></div>`}
function habitsPage(){const list=state.habits.filter(h=>!!h.archivedAt===archiveView);return `<div class="section-title"><div class="segmented"><button data-archive-view="false" class="${!archiveView?'active':''}">Активные (${state.habits.filter(h=>!h.archivedAt).length})</button><button data-archive-view="true" class="${archiveView?'active':''}">Архив (${state.habits.filter(h=>h.archivedAt).length})</button></div><small>${list.length} привычек</small></div>${list.length?list.map(h=>row(h,true)).join(''):archiveView?'<div class="empty">Архив пуст. Здесь будут привычки, которые вы отложили.</div>':starter()}`}
function render(){const focusData=document.activeElement?.dataset;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});$('#page-label').textContent={today:'Сегодня',stats:'Статистика',habits:'Мои привычки'}[view];$('#date-label').textContent=R.parse(selected).toLocaleDateString('ru',{weekday:'long',day:'numeric',month:'long'}).toUpperCase();$('#title').innerHTML={today:'Ваш день<span>.</span>',stats:'Ваш прогресс в деталях<span>.</span>',habits:'Ваши привычки<span>.</span>'}[view];$('#subtitle').textContent={today:'Сосредоточьтесь на том, что важно сегодня.',stats:'Замечайте регулярность, а не только идеальные дни.',habits:'Настройте цели, которые подходят именно вам.'}[view];$('#storage-warning').hidden=!blocked;$('#content').innerHTML=view==='today'?todayPage():view==='stats'?statsPage():habitsPage();if(focusData)for(const attr of ['plus','minus','check','filter','week'])if(focusData[attr]!==undefined){document.querySelector(`[data-${attr}="${CSS.escape(focusData[attr])}"]`)?.focus({preventScroll:true});break}}
function openEditor(id,templateIndex){const h=state.habits.find(h=>h.id===id),preset=templates[templateIndex];editing=h?.id||null;editSnapshot=h?JSON.stringify(h):'';const defaults={name:'',type:'check',target:1,unit:'раз',step:1,period:'morning',icon:'☀',schedule:'days',frequency:3,days:[0,1,2,3,4,5,6]},data={...defaults,...(h||preset||{})},f=$('#habit-form');f.reset();$('#dialog-title').textContent=h?'Настроить привычку':'Новая привычка';for(const field of ['name','type','target','unit','step','period','icon','schedule','frequency'])f.elements[field].value=data[field];$('#days').innerHTML='<legend>Дни недели</legend>'+names.map((n,i)=>`<label><input type="checkbox" value="${i}" ${data.days.includes(i)?'checked':''}><span>${n}</span></label>`).join('');$('#edit-history-note').hidden=!h;$('#form-error').textContent='';scheduleFields();$('#editor').showModal();f.elements.name.focus()}
function scheduleFields(){const f=$('#habit-form'),weekly=f.elements.schedule.value==='weekly',check=f.elements.type.value==='check';$('#days').hidden=weekly;$('#weekly-label').hidden=!weekly;f.elements.frequency.disabled=!weekly;$('#goal-details').hidden=check;for(const k of ['target','unit','step'])f.elements[k].disabled=check;if(f.elements.type.value==='minutes'){f.elements.unit.value='мин.';f.elements.unit.readOnly=true}else f.elements.unit.readOnly=false}
$('#habit-form').addEventListener('change',scheduleFields);
$('#habit-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,days=[...$('#days').querySelectorAll('input:checked')].map(i=>Number(i.value)),name=f.elements.name.value.trim();if(!name||(!days.length&&f.elements.schedule.value==='days')){$('#form-error').textContent=!name?'Введите название привычки.':'Выберите хотя бы один день недели.';return}const changes={name,type:f.elements.type.value,target:f.elements.type.value==='check'?1:Number(f.elements.target.value),unit:f.elements.unit.value.trim()||'раз',step:Number(f.elements.step.value)||1,period:f.elements.period.value,icon:f.elements.icon.value,schedule:f.elements.schedule.value,frequency:Number(f.elements.frequency.value)||3,days:days.length?days:[0,1,2,3,4,5,6]};let effective=null;const ok=await transact(s=>{if(editing){const h=s.habits.find(h=>h.id===editing);if(!h||JSON.stringify(h)!==editSnapshot)throw Error('Привычка изменилась в другой вкладке. Откройте редактор заново.');effective=R.revise(h,changes)}else{const h={...changes,id:crypto.randomUUID(),created:R.today(),archivedAt:null,pauses:[]};h.revisions=[{from:h.created,...R.config(h)}];s.habits.push(h)}});if(ok){$('#editor').close();notify(effective?`Новая цель начнёт действовать с ${dateText(effective)}. История сохранена.`:'Привычка сохранена')}});
function openValue(id){const h=state.habits.find(h=>h.id===id),c=R.configAt(h,selected);$('#progress-form').dataset.id=id;$('#progress-form').dataset.date=selected;$('#progress-title').textContent=h.name;$('#progress-description').textContent=`${dateText(selected)} · цель ${c.target} ${c.unit}`;$('#amount').value=R.value(state,h,selected);$('#progress-dialog').showModal();$('#amount').select()}
$('#progress-form').onsubmit=async e=>{e.preventDefault();if(await progress(e.target.dataset.id,Number($('#amount').value),e.target.dataset.date))$('#progress-dialog').close()};
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportData(){if(blocked){notify('Текущие данные не прочитаны. Восстановите проверенную копию.');return}download(state,`ritm-${R.today()}.json`);notify('Резервная копия скачана')}
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error();importData=R.migrate(JSON.parse(await file.text()));$('#import-summary').textContent=`В копии: ${importData.habits.length} привычек и ${Object.keys(importData.logs).length} дней с отметками. Текущие данные будут заменены. Перед заменой сохранится локальная копия.`;$('#import-dialog').showModal()}catch{notify('Копия повреждена или имеет неподдерживаемый формат. Текущие данные не изменены.')}finally{e.target.value=''}};
$('#confirm-import').onclick=async()=>{if(!importData)return;if(RitmCloud.launched){const imported=importData;if(await transact(s=>{s.version=imported.version;s.habits=imported.habits;s.logs=imported.logs})){importData=null;$('#import-dialog').close();notify('Копия сохранена в Telegram')}return;}try{const current=localStorage.getItem(KEY);if(current)localStorage.setItem('ritm-before-import',current);localStorage.setItem(KEY,JSON.stringify(importData));state=importData;blocked=false;importData=null;$('#import-dialog').close();render();notify('Данные восстановлены')}catch{notify('Не удалось восстановить копию. Текущие данные сохранены.')}};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.view){view=d.view;if(view==='today')selected=R.today();render()}if(d.create!==undefined||b.id==='add')openEditor();if(d.template!==undefined)openEditor(null,Number(d.template));if(d.close)$('#'+d.close).close();if(d.edit)openEditor(d.edit);if(d.value)openValue(d.value);if(d.date){selected=d.date;view='today';filter='all';render()}if(d.today!==undefined){selected=R.today();filter='all';render()}if(d.week){selected=R.shift(selected,Number(d.week));if(selected>R.today())selected=R.today();filter='all';render()}if(d.filter){filter=d.filter;render()}if(d.archiveView){archiveView=d.archiveView==='true';render()}if(d.month){const date=R.parse(month+'-01');date.setMonth(date.getMonth()+Number(d.month));month=R.key(date).slice(0,7);render()}for(const action of ['plus','minus','check'])if(d[action]){const h=state.habits.find(h=>h.id===d[action]),c=R.configAt(h,selected),v=R.value(state,h,selected);progress(h.id,action==='check'?(R.done(state,h,selected)?0:c.target):Math.max(0,Math.min(100000,v+(action==='plus'?c.step:-c.step))))}if(d.archive){let before,after;const ok=await transact(s=>{const h=s.habits.find(h=>h.id===d.archive);if(!h)throw Error('Привычка больше не существует.');before=structuredClone(h);h.archivedAt?R.restore(h):R.archive(h);after=JSON.stringify(h)});if(ok)notify(before.archivedAt?'Привычка возвращена':'Привычка в архиве. История сохранена.',()=>transact(s=>{const index=s.habits.findIndex(h=>h.id===d.archive);if(index<0||JSON.stringify(s.habits[index])!==after)throw Error('Привычка уже изменена.');s.habits[index]=before}))}if(d.export!==undefined||b.id==='export')exportData();if(d.import!==undefined||b.id==='import')$('#import-file').click();if(b.id==='undo'&&undoAction){const action=undoAction;undoAction=null;if(await action())notify('Действие отменено')}if(d.recover!==undefined){try{const raw=localStorage.getItem('ritm-before-import')||localStorage.getItem('ritm-before-v2');if(!raw)return notify('Локальная резервная копия пока не создана.');download(JSON.parse(raw),`ritm-recovery-${R.today()}.json`)}catch{notify('Не удалось прочитать локальную копию.')}}});
document.addEventListener('change',e=>{if(e.target.id==='stats-habit'){statsHabit=e.target.value;render()}});$('.brand').onclick=e=>{e.preventDefault();view='today';selected=R.today();render()};
window.addEventListener('storage',e=>{if(RitmCloud.launched||e.key!==KEY)return;try{state=e.newValue?R.migrate(JSON.parse(e.newValue)):{version:2,habits:[],logs:{}};blocked=false;render()}catch{blocked=true;render()}});
function rollover(){const now=R.today();if(now!==lastDay){if(selected===lastDay)selected=now;month=now.slice(0,7);lastDay=now;render()}}document.addEventListener('visibilitychange',()=>{if(!document.hidden)rollover()});setInterval(rollover,30000);
async function startCloud(){blocked=true;document.documentElement.classList.add('cloud-loading');try{state=R.migrate(await RitmCloud.load());blocked=false;if(state.language&&state.language!==DayLanguage.current){DayLanguage.navigate(state.language);return}render()}catch(e){RitmCloud.status(e.message);notify(e.message)}finally{document.documentElement.classList.remove('cloud-loading')}}
window.addEventListener('ritm:cloud-update',e=>{state=R.migrate(e.detail);render()});
window.addEventListener('ritm:cloud-conflict',e=>{state=R.migrate(e.detail);render()});
window.addEventListener('ritm:cloud-retry',()=>{if(!window.RitmWriting)startCloud()});
RitmCloud.boot();if(RitmCloud.launched){render();startCloud()}else{load();render();}
if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'read_habits',description:'Read scheduled habits and their progress for the selected date.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({date:selected,habits:state.habits.filter(h=>R.scheduled(state,h,selected)).map(h=>({id:h.id,name:h.name,target:R.configAt(h,selected).target,value:R.value(state,h,selected)}))})})).catch(()=>{})}catch{}
